from query import parse_query


def test_empty():
    assert parse_query('  ') == {'terms': [], 'filters': {}, 'exclude': [], 'exclude_filters': {}}


def test_terms_lowercased_in_order():
    assert parse_query('Red Car')['terms'] == ['red', 'car']


def test_filters():
    assert parse_query('status:open')['filters'] == {'status': 'open'}


def test_quoted_value():
    assert parse_query('title:"hello world"')['filters'] == {'title': 'hello world'}


def test_quoted_term():
    assert parse_query('"big dog" cat')['terms'] == ['big dog', 'cat']


def test_negated_term():
    out = parse_query('car -spam')
    assert out['terms'] == ['car'] and out['exclude'] == ['spam']


def test_negated_filter():
    assert parse_query('-status:closed')['exclude_filters'] == {'status': 'closed'}


def test_repeated_key_collects():
    assert parse_query('tag:a tag:b')['filters'] == {'tag': ['a', 'b']}

