class Stage:
    name = ''

    def process(self, event):
        raise NotImplementedError


class Parse(Stage):
    name = 'parse'

    def process(self, event):
        return dict(event, parsed=True)


class Store(Stage):
    name = 'store'

    def process(self, event):
        return dict(event, stored=True)


DEFAULT_ORDER = ['parse', 'store']

