import pipeline
import registry
import schema


def test_registered():
    assert 'enrich' in registry.REGISTRY
    assert isinstance(registry.build('enrich'), pipeline.Stage)


def test_order():
    order = pipeline.DEFAULT_ORDER
    assert order.index('parse') < order.index('enrich') < order.index('store')


def test_schema_declared():
    assert sorted(schema.EMITS['enrich']) == ['device', 'geo']


def test_emits_fields():
    out = registry.build('enrich').process({'ip': '8.8.8.8', 'user_agent': 'Mozilla'})
    assert 'geo' in out and 'device' in out


def test_unknown_defaults():
    out = registry.build('enrich').process({})
    assert out['geo'] == 'unknown' and out['device'] == 'unknown'


def test_does_not_mutate():
    event = {'ip': '1.1.1.1', 'user_agent': 'curl'}
    registry.build('enrich').process(event)
    assert event == {'ip': '1.1.1.1', 'user_agent': 'curl'}


def test_every_registered_stage_has_schema():
    assert set(registry.REGISTRY) == set(schema.EMITS)

