import time


class TokenBucket:
    def __init__(self, capacity, refill_per_second):
        self.capacity = capacity
        self.tokens = capacity
        self.refill_per_second = refill_per_second

    def allow(self, cost=1):
        if self.tokens >= cost:
            self.tokens -= cost
            return True
        return False
